-- SaaS dataset: a B2B subscription product (accounts, users, subscriptions, invoices, events, tickets).

PRAGMA foreign_keys = ON;


CREATE TABLE accounts (
  account_id        INTEGER PRIMARY KEY,
  company           TEXT NOT NULL,
  industry          TEXT NOT NULL,
  country           TEXT NOT NULL,
  created_on        DATE NOT NULL,
  parent_account_id INTEGER REFERENCES accounts(account_id)
);
CREATE TABLE app_users (
  user_id    INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(account_id),
  email      TEXT NOT NULL,
  role       TEXT NOT NULL CHECK (role IN ('owner','admin','member')),
  created_on DATE NOT NULL,
  last_login DATETIME
);
CREATE TABLE subscriptions (
  subscription_id INTEGER PRIMARY KEY,
  account_id      INTEGER NOT NULL REFERENCES accounts(account_id),
  plan            TEXT NOT NULL CHECK (plan IN ('free','starter','pro','enterprise')),
  mrr             REAL NOT NULL,
  started_on      DATE NOT NULL,
  ended_on        DATE
);
CREATE TABLE invoices (
  invoice_id INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(account_id),
  issued_on  DATE NOT NULL,
  amount     REAL NOT NULL,
  paid_on    DATE,
  status     TEXT NOT NULL CHECK (status IN ('paid','open','void'))
);
CREATE TABLE features (
  feature_name TEXT PRIMARY KEY,
  is_core      INTEGER NOT NULL
);
CREATE TABLE events (
  event_id    INTEGER PRIMARY KEY,
  account_id  INTEGER NOT NULL REFERENCES accounts(account_id),
  user_id     INTEGER NOT NULL REFERENCES app_users(user_id),
  event_name  TEXT NOT NULL,
  occurred_at DATETIME NOT NULL
);
CREATE TABLE tickets (
  ticket_id  INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(account_id),
  opened_at  DATETIME NOT NULL,
  closed_at  DATETIME,
  priority   TEXT NOT NULL CHECK (priority IN ('low','normal','high','urgent')),
  category   TEXT NOT NULL,
  csat       INTEGER CHECK (csat BETWEEN 1 AND 5)
);

